import enum
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
SyntaxSpecification = list
class Node:
    def __init__(self, flag=None, alias=None, flag_followed_by_equals=False, choices=None, arity=Arity.OPTIONAL, dash_as_stdin=False, **kw):
        self.kind=type(self).__name__; self.flag=flag; self.alias=alias or []; self.eq=flag_followed_by_equals
        self.choices=choices; self.arity=arity; self.dash_as_stdin=dash_as_stdin; self.kw=kw
class Flag(Node):
    def __init__(self, flag, alias=None): super().__init__(flag=flag, alias=alias)
for n in "Path Integer Int Number String Other Selection List Regex Glob Separator Char".split():
    globals()[n]=type(n,(Node,),{})
